        DiscoveryCard(id: "sunnah_bukhari_464", kind: .sunnah, arabic: "طُوفِي مِنْ وَرَاءِ النَّاسِ وَأَنْتِ رَاكِبَةٌ"),
        DiscoveryCard(id: "sunnah_bukhari_469", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_475", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_478", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_480", kind: .sunnah, arabic: "يَا عَبْدَ اللَّهِ بْنَ عَمْرٍو، كَيْفَ بِكَ إِذَا بَقِيتَ فِي حُثَالَةٍ مِنَ النَّاسِ بِهَذَا"),
        DiscoveryCard(id: "sunnah_bukhari_481", kind: .sunnah, arabic: "إِنَّ الْمُؤْمِنَ لِلْمُؤْمِنِ كَالْبُنْيَانِ، يَشُدُّ بَعْضُهُ بَعْضًا"),
        DiscoveryCard(id: "sunnah_bukhari_484", kind: .sunnah, arabic: nil),
