        DiscoveryCard(id: "sunnah_bukhari_519", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_524", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_529", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_532", kind: .sunnah, arabic: "اعْتَدِلُوا فِي السُّجُودِ، وَلاَ يَبْسُطْ ذِرَاعَيْهِ كَالْكَلْبِ، وَإِذَا بَزَقَ فَلاَ يَبْزُقَنَّ بَيْنَ يَدَيْهِ وَلاَ عَنْ يَمِينِهِ، فَإِنَّهُ يُنَاجِي رَبَّهُ"),
        DiscoveryCard(id: "sunnah_bukhari_533", kind: .sunnah, arabic: "إِذَا اشْتَدَّ الْحَرُّ فَأَبْرِدُوا عَنِ الصَّلاَةِ، فَإِنَّ شِدَّةَ الْحَرِّ مِنْ فَيْحِ جَهَنَّمَ"),
        DiscoveryCard(id: "sunnah_bukhari_538", kind: .sunnah, arabic: "أَبْرِدُوا بِالظُّهْرِ، فَإِنَّ شِدَّةَ الْحَرِّ مِنْ فَيْحِ جَهَنَّمَ"),
        DiscoveryCard(id: "sunnah_bukhari_542", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_543", kind: .sunnah, arabic: nil),
