        DiscoveryCard(id: "sunnah_bukhari_546", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_548", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_551", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_552", kind: .sunnah, arabic: "الَّذِي تَفُوتُهُ صَلاَةُ الْعَصْرِ كَأَنَّمَا وُتِرَ أَهْلَهُ وَمَالَهُ"),
        DiscoveryCard(id: "sunnah_bukhari_553", kind: .sunnah, arabic: "مَنْ تَرَكَ صَلاَةَ الْعَصْرِ فَقَدْ حَبِطَ عَمَلُهُ"),
        DiscoveryCard(id: "sunnah_bukhari_556", kind: .sunnah, arabic: "إِذَا أَدْرَكَ أَحَدُكُمْ سَجْدَةً مِنْ صَلاَةِ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَلْيُتِمَّ صَلاَتَهُ، وَإِذَا أَدْرَكَ سَجْدَةً مِنْ صَلاَةِ الصُّبْحِ قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَلْيُتِمَّ صَلاَتَهُ"),
        DiscoveryCard(id: "sunnah_bukhari_559", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_561", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_562", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_563", kind: .sunnah, arabic: "لاَ تَغْلِبَنَّكُمُ الأَعْرَابُ عَلَى اسْمِ صَلاَتِكُمُ الْمَغْرِبِ"),
        DiscoveryCard(id: "sunnah_bukhari_568", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_574", kind: .sunnah, arabic: "مَنْ صَلَّى الْبَرْدَيْنِ دَخَلَ الْجَنَّةَ"),
        DiscoveryCard(id: "sunnah_bukhari_577", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_578", kind: .sunnah, arabic: nil),
        DiscoveryCard(id: "sunnah_bukhari_579", kind: .sunnah, arabic: "مَنْ أَدْرَكَ مِنَ الصُّبْحِ رَكْعَةً قَبْلَ أَنْ تَطْلُعَ الشَّمْسُ فَقَدْ أَدْرَكَ الصُّبْحَ، وَمَنْ أَدْرَكَ رَكْعَةً مِنَ الْعَصْرِ قَبْلَ أَنْ تَغْرُبَ الشَّمْسُ فَقَدْ أَدْرَكَ الْعَصْرَ"),
        DiscoveryCard(id: "sunnah_bukhari_580", kind: .sunnah, arabic: "مَنْ أَدْرَكَ رَكْعَةً مِنَ الصَّلاَةِ فَقَدْ أَدْرَكَ الصَّلاَةَ"),
        DiscoveryCard(id: "sunnah_bukhari_581", kind: .sunnah, arabic: nil),
